content = '''use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

const VERSION: &str = \"4.3.1\";

#[derive(Debug, Clone, Default)]
struct Options {
    suggest: bool,
    syntax: bool,
    syntax_suggest: bool,
    transform: bool,
    check: bool,
    replace: bool,
    files: Vec<String>,
}

fn parse_args() -> Options {
    let args: Vec<String> = env::args().collect();
    let mut opts = Options::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        if arg == \"--help\" || arg == \"-h\" {
            print_help();
            process::exit(0);
        } else if arg == \"--version\" {
            println!(\"{}\", VERSION);
            process::exit(0);
        } else if arg == \"--suggest\" {
            opts.suggest = true;
        } else if arg == \"--syntax\" {
            opts.syntax = true;
        } else if arg == \"--syntax-suggest\" {
            opts.syntax_suggest = true;
        } else if arg == \"--transform\" {
            opts.transform = true;
        } else if arg == \"--check\" {
            opts.check = true;
        } else if arg == \"--replace\" {
            opts.replace = true;
        } else if arg == \"--\" {
            break;
        } else if arg.starts_with('-') {
            eprintln!(\"Error: Unknown option {}\", arg);
            process::exit(1);
        } else {
            opts.files.push(arg.clone());
        }

        i += 1;
    }

    opts
}
'''
