fn highlight_syntax(input: &str) -> String {
    let mut result = String::new();
    let mut chars = input.chars().peekable();
    let mut i = 0;

    while i < input.len() {
        let c = input.chars().nth(i).unwrap();

        // Check for keywords
        if is_keyword(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for here document
        if i + 2 < input.len() && input[i..].starts_with("<<") {
            let rest = &input[i+2..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                if ch == '"' || ch == '\'' || ch == '`' {
                    result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", ch));
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                    continue;
                }
                result.push(ch);
                i += ch.len_utf8();
                j += ch.len_utf8();
            }
            continue;
        }

        // Check for variables
        if c == '$' && i + 1 < input.len() {
            let rest = &input[i+1..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                if ch.is_alphanumeric() || ch == '_' || ch == '.' {
                    result.push_str(&format!("\u{001b}[0;38;2;63;127;207m{}\u{001b}m", ch));
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                } else {
                    result.push(ch);
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                }
            }
            continue;
        }

        // Check for quotes
        if c == '"' || c == '\'' || c == '`' {
            result.push_str(&format!("\u{001b}[0;38;2;255;0;0m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for operators
        if is_operator(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for special characters
        if is_special(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Default: plain text
        result.push(c);
        i += c.len_utf8();
    }

    result
}

fn is_keyword(s: &str) -> bool {
    let keywords = ["if", "then", "else", "fi", "while", "do", "done", "for", "in", "case", "esac", "function", "return", "exit", "break", "continue", "local", "declare", "export", "unset", "read", "echo", "printf", "test", "[", "]", "true", "false", "shift", "getopts", "trap", "wait", "exec", "alias", "unalias", "type", "command", "hash", "enable", "disable", "typeset", "ulimit", "umask", "shopt", "opterr", "optind", "OPTIND", "OPTERR", "OPTARG", "OPTIND", "OPTERR", "OPTARG"];
    keywords.iter().any(|k| s.starts_with(k) && (s.len() == k.len() || !s.chars().nth(k.len()).unwrap().is_alphabetic()))
}

fn is_operator(s: &str) -> bool {
    let operators = ["==", "!=", "<", ">", "<=", ">=", "<<", ">>", "&", "|", ";", "&&", "||", "(", ")", "{", "}", "[", "]", ",", ":", "!", "~", "*", "/", "%", "+", "-", "^", "&", "|", "<<", ">>", "?", "`", "\\", "'", "\""];
    operators.iter().any(|op| s.starts_with(op))
