                if ch == '"' || ch == '\'' || ch == '`' {
                    result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", ch));
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                    continue;
                }
                result.push(ch);
                i += ch.len_utf8();
                j += ch.len_utf8();
            }
            continue;
        }

        // Check for variables
        if c == '$' && i + 1 < input.len() {
            let rest = &input[i+1..];
            let mut j = 0;
            let mut var_end = j;
            while var_end < rest.len() {
                let ch = rest.chars().nth(var_end).unwrap();
                if ch.is_alphanumeric() || ch == '_' || ch == '.' {
