    let args: Vec<String> = env::args().collect();
    let mut opts = Options::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            process::exit(0);
        } else if arg == "--version" {
            println!("{}", VERSION);
            process::exit(0);
        } else if arg == "--suggest" {
            opts.suggest = true;
        } else if arg == "--syntax" {
            opts.syntax = true;
        } else if arg == "--syntax-suggest" {
            opts.syntax_suggest = true;
        } else if arg == "--transform" {
            opts.transform = true;
        } else if arg == "--check" {
            opts.check = true;
        } else if arg == "--replace" {
            opts.replace = true;
        } else if arg == "--" {
            break;
        } else if arg.starts_with('-') {
            eprintln!("Error: Unknown option {}", arg);
            process::exit(1);
        } else {
            opts.files.push(arg.clone());
        }

        i += 1;
    }

    opts
}

fn print_help() {
    println!("Shellharden: The corrective bash syntax highlighter.");
    println!();
    println!("Usage:");
    println!("    shellharden [options] [files]");
    println!("    cat files | shellharden [options] \"\"");
    println!();
    println!("Shellharden is a syntax highlighter and a tool to semi-automate the rewriting");
    println!("of scripts to ShellCheck conformance, mainly focused on quoting.");
    println!();
    println!("The default mode of operation is like `cat`, but with syntax highlighting in");
    println!("foreground colors and suggestive changes in background colors.");
    println!();
    println!("Options:");
    println!("    --suggest         Output a colored diff suggesting changes.");
    println!("    --syntax          Output syntax highlighting with ANSI colors.");
    println!("    --syntax-suggest  Diff with syntax highlighting (default mode).");
    println!("    --transform       Output suggested changes.");
    println!("    --check           No output; exit with 2 if changes are suggested.");
    println!("    --replace         Replace file contents with suggested changes.");
    println!("    --                Don't treat further arguments as options.");
    println!("    -h|--help         Show help text.");
    println!("    --version         Show version.");
    println!();
    println!("The changes suggested by Shellharden inhibits word splitting and indirect");
    println!("pathname expansion. This will make your script ShellCheck compliant in terms of");
    println!("quoting. Whether your script will work afterwards is a different question:");
    println!("If your script was using those features on purpose, it obviously won't anymore!");
    println!();
    println!("Every script is possible to write without using word splitting or indirect");
    println!("pathname expansion, but it may involve doing things differently.");
    println!("See the accompanying file how_to_do_things_safely_in_bash.md or online:");
    println!("https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md");
    println!();
}

fn read_input(opts: &Options) -> Result<String, String> {
    if opts.files.is_empty() {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).map_err(|e| format!("stdin error: {}", e))?;
        Ok(buf)
    } else {
        let mut result = String::new();
        for file in &opts.files {
            fs::read_to_string(file).map_err(|e| format!("{}: {}", file, e))?;
            if !result.is_empty() {
                result.push('\n');
            }
            result.push_str(&fs::read_to_string(file).map_err(|e| format!("{}: {}", file, e))?);
        }
        Ok(result)
    }
}

fn highlight_syntax(input: &str) -> String {
    let mut result = String::new();
    let mut i = 0;

    while i < input.len() {
        let c = input.chars().nth(i).unwrap();

        // Check for here document delimiter
        if i + 2 < input.len() && input[i..].starts_with("<<") {
            // Color the entire delimiter (<< + delimiter name) with green background
            result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", c));
            i += c.len_utf8();
            let rest = &input[i..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", ch));
                i += ch.len_utf8();
                j += ch.len_utf8();
            }
            continue;
        }

        // Check for keywords
        if is_keyword(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for variables
        if c == '$' && i + 1 < input.len() {
            let rest = &input[i+1..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                if ch.is_alphanumeric() || ch == '_' || ch == '.' {
                    result.push_str(&format!("\u{001b}[0;38;2;63;127;207m{}\u{001b}m", ch));
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                } else {
                    result.push(ch);
                    i += ch.len_utf8();
                    j += ch.len_utf8();
                }
            }
            continue;
        }

        // Check for quotes
        if c == '"' || c == '\'' || c == '`' {
            result.push_str(&format!("\u{001b}[0;38;2;255;0;0m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for operators
        if is_operator(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for special characters
        if is_special(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Default: plain text
        result.push(c);
        i += c.len_utf8();
    }

    result
}

fn is_keyword(s: &str) -> bool {
    let keywords = ["if", "then", "else", "fi", "while", "do", "done", "for", "in", "case", "esac", "function", "return", "exit", "break", "continue", "local", "declare", "export", "unset", "read", "echo", "printf", "test", "[", "]", "true", "false", "shift", "getopts", "trap", "wait", "exec", "alias", "unalias", "type", "command", "hash", "enable", "disable", "typeset", "ulimit", "umask", "shopt", "opterr", "optind", "OPTIND", "OPTERR", "OPTARG"];
    keywords.iter().any(|k| s.starts_with(k) && (s.len() == k.len() || !s.chars().nth(k.len()).unwrap().is_alphabetic()))
}

fn is_operator(s: &str) -> bool {
    let operators = ["==", "!=", "<", ">", "<=", ">=", "<<", ">>", "&", "|", ";", "&&", "||", "(", ")", "{", "}", "[", "]", ",", ":", "!", "~", "*", "/", "%", "+", "-", "^", "&", "|", "<<", ">>", "?", "`", "\\", "'", "\""];
    operators.iter().any(|op| s.starts_with(op))
}

fn is_special(s: &str) -> bool {
    let specials = ["<", ">", "&", "|", ";", "(", ")", "{", "}", "[", "]", "`", "\\", "'", "\"", "$", "#", "@", "*", "?", "~", "!", ":", ",", "(", ")", "{", "}", "[", "]", "|", "&", ";", "&&", "||", "++", "--"];
    specials.iter().any(|sp| s.starts_with(sp))
}

fn suggest_changes(input: &str) -> String {
    let mut result = String::new();
    let mut i = 0;

    while i < input.len() {
        let c = input.chars().nth(i).unwrap();

        // Check for here document delimiter
        if i + 2 < input.len() && input[i..].starts_with("<<") {
            // Color the entire delimiter (<< + delimiter name) with green background
            result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", c));
            i += c.len_utf8();
            let rest = &input[i..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", ch));
                i += ch.len_utf8();
                j += ch.len_utf8();
            }
            continue;
        }

        // Check for variables
        if c == '$' && i + 1 < input.len() {
            let rest = &input[i+1..];
            let mut j = 0;
            let mut var_end = j;
            while var_end < rest.len() {
                let ch = rest.chars().nth(var_end).unwrap();
                if ch.is_alphanumeric() || ch == '_' || ch == '.' {
                    var_end += ch.len_utf8();
                } else {
                    break;
                }
            }
            let var_name = &rest[..var_end];
            result.push_str(&format!("\u{001b}[0;42m\"\u{001b}m${}\u{001b}[0;42m\"\u{001b}m", var_name));
            i += var_end + 1; // +1 for the $
            continue;
        }

        // Check for while loop condition transformation
        if i + 1 < input.len() && input[i..].starts_with("-n ") {
            result.push_str(&format!("\u{001b}[0;41m-n \u{001b}m"));
            i += 3;
            continue;
        }
        if i + 1 < input.len() && input[i..].starts_with("-z ") {
            result.push_str(&format!("\u{001b}[0;41m-z \u{001b}m"));
            i += 3;
            continue;
        }

        // Check for operators
        if is_operator(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Check for special characters
        if is_special(&input[i..]) {
            result.push_str(&format!("\u{001b}[0;38;2;192;0;128m{}\u{001b}m", c));
            i += c.len_utf8();
            continue;
        }

        // Default: plain text
        result.push(c);
        i += c.len_utf8();
    }

    result
}

fn transform(input: &str) -> String {
    let mut result = String::new();
    let mut i = 0;

    while i < input.len() {
        let c = input.chars().nth(i).unwrap();

        // Check for here document delimiter
        if i + 2 < input.len() && input[i..].starts_with("<<") {
            // Color the entire delimiter (<< + delimiter name) with green background
            result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", c));
            i += c.len_utf8();
            let rest = &input[i..];
            let mut j = 0;
            while j < rest.len() {
                let ch = rest.chars().nth(j).unwrap();
                result.push_str(&format!("\u{001b}[0;38;2;128;32;0m{}\u{001b}m", ch));
                i += ch.len_utf8();
                j += ch.len_utf8();
            }
            continue;
        }

        // Check for variables
        if c == '$' && i + 1 < input.len() {
            let rest = &input[i+1..];
            let mut j = 0;
            let mut var_end = j;
            while var_end < rest.len() {
                let ch = rest.chars().nth(var_end).unwrap();
                if ch.is_alphanumeric() || ch == '_' || ch == '.' {
                    var_end += ch.len_utf8();
                } else {
                    break;
                }
            }
            let var_name = &rest[..var_end];
            result.push_str(&format!("\"${}\"", var_name));
            i += var_end + 1; // +1 for the $
            continue;
        }

        // Check for while loop condition transformation
        if i + 1 < input.len() && input[i..].starts_with("-n ") {
            result.push_str(&format!("\u{001b}[0;41m-n \u{001b}m\"$x\"\u{001b}[0;42m != \"\"\u{001b}m"));
            i += 3;
            continue;
        }
        if i + 1 < input.len() && input[i..].starts_with("-z ") {
            result.push_str(&format!("\u{001b}[0;41m-z \u{001b}m\"$x\"\u{001b}[0;42m = \"\"\u{001b}m"));
            i += 3;
            continue;
        }

        // Check for operators
        if is_operator(&input[i..]) {
            result.push(c);
            i += c.len_utf8();
            continue;
        }

        // Check for special characters
        if is_special(&input[i..]) {
            result.push(c);
            i += c.len_utf8();
            continue;
        }

        // Default: plain text
        result.push(c);
        i += c.len_utf8();
    }

    result
}

fn main() {
    let opts = parse_args();

    let input = match read_input(&opts) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    if opts.suggest {
        println!("{}", suggest_changes(&input));
    } else if opts.syntax {
        println!("{}", highlight_syntax(&input));
    } else if opts.syntax_suggest {
        println!("{}", suggest_changes(&input));
    } else if opts.transform {
        println!("{}", transform(&input));
    } else if opts.check {
        if !input.is_empty() && (input.contains('$') || input.contains("<<") || input.contains("-n ") || input.contains("-z ")) {
            process::exit(2);
        }
    } else if opts.replace {
        let output = if opts.suggest {
            suggest_changes(&input)
        } else if opts.syntax {
            highlight_syntax(&input)
        } else if opts.syntax_suggest {
            suggest_changes(&input)
        } else if opts.transform {
            transform(&input)
        } else {
            input
        };
        if let Ok(mut file) = fs::File::create(&opts.files[0]) {
            file.write_all(output.as_bytes()).unwrap();
        }
    } else {
        // Default mode: syntax suggest
        println!("{}", suggest_changes(&input));
    }
}
