diff --git a/src/main.rs b/src/main.rs
new file mode 100644
index 0000000..e69de29
--- /dev/null
+++ b/src/main.rs
@@ -0,0 +1,1443 @@
+use std::env;
+use std::fs;
+use std::io::{self, Read, Write};
+use std::process;
+
+const VERSION: &str = "4.3.1";
+
+#[derive(Debug, Clone, Default)]
+struct Options {
+    suggest: bool,
+    syntax: bool,
+    syntax_suggest: bool,
+    transform: bool,
+    check: bool,
+    replace: bool,
+    files: Vec<String>,
+}
+
+fn parse_args() -> Options {
+    let mut opts = Options::default();
+    let args: Vec<String> = env::args().collect();
+
+    for arg in args.iter().skip(1) {
+        match arg.as_str() {
+            "--help" => {
+                print_help();
+                process::exit(0);
+            }
+            "--version" => {
+                println!("{}", VERSION);
+                process::exit(0);
+            }
+            "--suggest" => {
+                opts.suggest = true;
+            }
+            "--syntax" => {
+                opts.syntax = true;
+            }
+            "--syntax-suggest" => {
+                opts.syntax_suggest = true;
+            }
+            "--transform" => {
+                opts.transform = true;
+            }
+            "--check" => {
+                opts.check = true;
+            }
+            "--replace" => {
+                opts.replace = true;
+            }
+            "--" => {
+                break;
+            }
+            _ => {
+                if arg.starts_with('-') {
+                    eprintln!("Unknown option: {}", arg);
+                    process::exit(1);
+                } else {
+                    opts.files.push(arg.to_string());
+                }
+            }
+        }
+    }
+
+    opts
+}
+
+fn print_help() {
+    println!("Usage: shellharden [OPTIONS] [FILES...]\n");
+    println!("Options:");
+    println!("  --suggest          Suggest changes with ANSI colors");
+    println!("  --syntax           Highlight syntax with ANSI colors");
+    println!("  --syntax-suggest   Highlight syntax and suggest changes with ANSI colors");
+    println!("  --transform        Transform input without ANSI colors");
+    println!("  --check            Check for issues and exit with code 2 if changes suggested");
+    println!("  --replace          Replace file contents with suggested changes");
+    println!("  --help             Show this help message");
+    println!("  --version          Show version number");
+    println!();
+    println!("If no options are specified, the default behavior is to suggest changes with ANSI colors.");
+    println!("If FILES are specified, the changes are written to those files.");
+}
+
+fn read_input() -> String {
+    let mut input = String::new();
+    if let Ok(mut stdin) = io::stdin() {
        stdin.read_to_string(&mut input).unwrap();
    }
    input
+}
+
+fn highlight_syntax(input: &str) -> String {
+    let mut output = String::new();
+    let mut in_string = false;
+    let mut in_single_quote = false;
+    let mut in_double_quote = false;
+    let mut in_backtick = false;
+    let mut in_dollar = false;
+    let mut in_bracket = false;
+    let mut in_paren = false;
+    let mut in_array = false;
+    let mut in_assoc_array = false;
+    let mut in_function = false;
+    let mut in_case = false;
+    let mut in_if = false;
+    let mut in_while = false;
+    let mut in_for = false;
+    let mut in_until = false;
+    let mut in_select = false;
+    let mut in_case_pattern = false;
+    let mut in_regex = false;
+    let mut in_glob = false;
+    let mut in_glob_pattern = false;
+    let mut in_glob_pattern_double = false;
+    let mut in_glob_pattern_single = false;
+    let mut in_glob_pattern_backtick = false;
+    let mut in_glob_pattern_dollar = false;
+    let mut in_glob_pattern_bracket = false;
+    let mut in_glob_pattern_paren = false;
