+use std::env;
+use std::fs;
+use std::io::{self, Read, Write};
+use std::process;
+
+const VERSION: &str = "4.3.1";
+
+#[derive(Debug, Clone, Default)]
+struct Options {
+    suggest: bool,
+    syntax: bool,
+    syntax_suggest: bool,
+    transform: bool,
+    check: bool,
+    replace: bool,
+    files: Vec<String>,
+}
+
+fn parse_args() -> Options {
+    let mut opts = Options::default();
+    let args: Vec<String> = env::args().collect();
+
+    for arg in args.iter().skip(1) {
+        match arg.as_str() {
+            "--help" => {
+                print_help();
+                process::exit(0);
+            }
+            "--version" => {
+                println!("{}", VERSION);
+                process::exit(0);
+            }
+            "--suggest" => {
+                opts.suggest = true;
+            }
+            "--syntax" => {
+                opts.syntax = true;
+            }
+            "--syntax-suggest" => {
+                opts.syntax_suggest = true;
+            }
+            "--transform" => {
+                opts.transform = true;
+            }
+            "--check" => {
+                opts.check = true;
+            }
+            "--replace" => {
+                opts.replace = true;
+            }
+            "--" => {
+                break;
+            }
+            _ => {
+                if arg.starts_with('-') {
+                    eprintln!("Unknown option: {}", arg);
+                    process::exit(1);
+                } else {
+                    opts.files.push(arg.to_string());
+                }
+            }
+        }
+    }
+
+    opts
+}
