    println!();
    println!("Options:");
    println!("    --suggest         Output a colored diff suggesting changes.");
    println!("    --syntax          Output syntax highlighting with ANSI colors.");
    println!("    --syntax-suggest  Diff with syntax highlighting (default mode).");
    println!("    --transform       Output suggested changes.");
    println!("    --check           No output; exit with 2 if changes are suggested.");
    println!("    --replace         Replace file contents with suggested changes.");
    println!("    --                Don't treat further arguments as options.");
    println!("    -h|--help         Show help text.");
    println!("    --version         Show version.");
    println!();
    println!("The changes suggested by Shellharden inhibits word splitting and indirect");
    println!("pathname expansion. This will make your script ShellCheck compliant in terms of");
    println!("quoting. Whether your script will work afterwards is a different question:");
    println!("If your script was using those features on purpose, it obviously won't anymore!");
