use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

const VERSION: &str = "4.3.1";

#[derive(Debug, Clone, Default)]
struct Options {
    suggest: bool,
    syntax: bool,
    syntax_suggest: bool,
    transform: bool,
    check: bool,
    replace: bool,
    files: Vec<String>,
}

fn parse_args() -> Options {
    let args: Vec<String> = env::args().collect();
    let mut opts = Options::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            process::exit(0);
        } else if arg == "--version" {
            println!("{}", VERSION);
            process::exit(0);
        } else if arg == "--suggest" {
            opts.suggest = true;
        } else if arg == "--syntax" {
            opts.syntax = true;
        } else if arg == "--syntax-suggest" {
            opts.syntax_suggest = true;
        } else if arg == "--transform" {
            opts.transform = true;
        } else if arg == "--check" {
            opts.check = true;
        } else if arg == "--replace" {
            opts.replace = true;
        } else if arg == "--" {
            break;
        } else if arg.starts_with('-') {
            eprintln!("Error: Unknown option {}", arg);
            process::exit(1);
        } else {
            opts.files.push(arg.clone());
        }

        i += 1;
    }

    opts
}

fn print_help() {
    println!("Shellharden: The corrective bash syntax highlighter.");
    println!();
    println!("Usage:");
    println!("    shellharden [options] [files]");
    println!("    cat files | shellharden [options] \"\"");
    println!();
    println!("Shellharden is a syntax highlighter and a tool to semi-automate the rewriting");
    println!("of scripts to ShellCheck conformance, mainly focused on quoting.");
    println!();
    println!("The default mode of operation is like `cat`, but with syntax highlighting in");
    println!("foreground colors and suggestive changes in background colors.");
    println!();
    println!("Options:");
    println!("    --suggest         Output a colored diff suggesting changes.");
    println!("    --syntax          Output syntax highlighting with ANSI colors.");
    println!("    --syntax-suggest  Diff with syntax highlighting (default mode).");
    println!("    --transform       Output suggested changes.");
    println!("    --check           No output; exit with 2 if changes are suggested.");
    println!("    --replace         Replace file contents with suggested changes.");
    println!("    --                Don't treat further arguments as options.");
    println!("    -h|--help         Show help text.");
    println!("    --version         Show version.");
    println!();
    println!("The changes suggested by Shellharden inhibits word splitting and indirect");
    println!("pathname expansion. This will make your script ShellCheck compliant in terms of");
    println!("quoting. Whether your script will work afterwards is a different question:");
    println!("If your script was using those features on purpose, it obviously won't anymore!");
    println!();
    println!("Every script is possible to write without using word splitting or indirect");
    println!("pathname expansion, but it may involve doing things differently.");
    println!("See the accompanying file how_to_do_things_safely_in_bash.md or online:");
    println!("https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md");
}

fn read_input(opts: &Options) -> Result<String, String> {
    if opts.files.is_empty() {
        let mut input = String::new();
        if let Ok(mut stdin) = io::stdin() {
            stdin.read_to_string(&mut input).unwrap();
        }
        Ok(input)
    } else {
        let mut output = String::new();
        for file in &opts.files {
            if let Ok(mut file) = fs::File::open(file) {
                file.read_to_string(&mut output).unwrap();
            } else {
                return Err(format!("Cannot open file: {}", file));
            }
        }
        Ok(output)
    }
}

