{"command": "cat > src/main.rs << 'RUSTEOF'
use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

const VERSION: &str = "4.3.1";

#[derive(Debug, Clone, Copy, PartialEq)]
enum Mode {
    Default,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, PartialEq)]
enum TokenType {
    Comment,
    Shebang,
    Keyword,
    Variable,
    CommandSub,
    ArrayExp,
    StringLit,
    Number,
    Operator,
    Punctuation,
    Whitespace,
    Other,
}

#[derive(Debug, Clone)]
struct Token {
    kind: TokenType,
    start: usize,
    end: usize,
    value: String,
}

#[derive(Debug, Clone)]
struct Suggestion {
    start: usize,
    end: usize,
    original: String,
    transformed: String,
}

fn tokenize(input: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut pos = 0;
    let chars: Vec<char> = input.chars().collect();

    while pos < chars.len() {
        let c = chars[pos];

        // Skip whitespace
        if c.is_whitespace() {
            let start = pos;
            while pos < chars.len() && chars[pos].is_whitespace() {
                pos += 1;
            }
            if start != pos {
                tokens.push(Token {
                    kind: TokenType::Whitespace,
                    start,
                    end: pos,
                    value: input[start..pos].to_string(),
                });
            }
            continue;
        }

        // Comments
        if c == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Comment,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Shebang
        if pos == 0 && c == '!' && pos + 1 < chars.len() && chars[pos + 1] == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Shebang,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // String literals
        if c == '"' || c == '\'' {
            let quote = c;
            let start = pos;
            pos += 1;
            while pos < chars.len() {
                if chars[pos] == '\\' && pos + 1 < chars.len() {
                    pos += 2;
                } else if chars[pos] == quote {
                    pos += 1;
                    break;
                } else {
                    pos += 1;
                }
            }
            tokens.push(Token {
                kind: TokenType::StringLit,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Numbers
        if c.is_ascii_digit() {
            let start = pos;
            while pos < chars.len() && chars[pos].is_ascii_digit() {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Number,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Operators and punctuation
        if c == '$' {
            let start = pos;
            if pos + 1 < chars.len() {
                let next = chars[pos + 1];
                if next == '?' || next == '#' || next == '!' || next == '*' || next == '@' {
                    pos += 1;
                    tokens.push(Token {
                        kind: TokenType::Variable,
                        start,
                        end: pos,
                        value: input[start..pos].to_string(),
                    });
                    continue;
                }
            }
            if pos + 1 < chars.len() && chars[pos + 1] == '(' {
                pos += 2;
                tokens.push(Token {
                    kind: TokenType::CommandSub,
                    start,
                    end: pos,
                    value: input[start..pos].to_string(),
                });
                continue;
            }
            if pos + 1 < chars.len() && chars[pos + 1] == '{' {
                let brace_start = pos + 1;
                pos += 1;
                while pos < chars.len() && chars[pos] != '}' {
                    pos += 1;
                }
                if pos < chars.len() {
                    pos += 1;
                }
                let value = input[brace_start..pos].to_string();
                if value.contains('@') || value.contains('*') {
                    tokens.push(Token {
                        kind: TokenType::ArrayExp,
                        start,
                        end: pos,
                        value,
                    });
                } else {
                    tokens.push(Token {
                        kind: TokenType::Variable,
                        start,
                        end: pos,
                        value,
                    });
                }
                continue;
            }
            pos += 1;
            tokens.push(Token {
                kind: TokenType::Variable,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c == '[' || c == ']' || c == '(' || c == ')' || c == '{' || c == '}' {
            let start = pos;
            pos += 1;
            tokens.push(Token {
                kind: TokenType::Punctuation,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c == '|' || c == '>' || c == '<' || c == ';' || c == '&' || c == '~' {
            let start = pos;
            pos += 1;
            tokens.push(Token {
                kind: TokenType::Operator,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Identifiers and keywords
        if c.is_alphabetic() || c == '_' {
            let start = pos;
            while pos < chars.len() && (chars[pos].is_alphanumeric() || chars[pos] == '_' || chars[pos] == '-') {
                pos += 1;
            }
            let value = input[start..pos].to_string();
            let kind = if value == "case" || value == "esac" || value == "in" || 
                        value == "do" || value == "done" || value == "for" || value == "while" ||
                        value == "if" || value == "then" || value == "else" || value == "fi" ||
                        value == "function" || value == "test" || value == "true" || value == "false" ||
                        value == "echo" || value == "printf" || value == "read" || value == "export" ||
                        value == "local" || value == "declare" || value == "unset" || value == "set" ||
                        value == "shift" || value == "return" || value == "exit" || value == "break" ||
                        value == "continue" || value == "select" || value == "until" {
                TokenType::Keyword
            } else {
                TokenType::Other
            };
            tokens.push(Token {
                kind,
                start,
                end: pos,
                value,
            });
            continue;
        }

        // Unknown character
        pos += 1;
    }

    tokens
}

fn find_suggestions(tokens: &[Token]) -> Vec<Suggestion> {
    let mut suggestions = Vec::new();

    for token in tokens {
        // Skip comments, whitespace, strings, numbers, operators, punctuation
        match token.kind {
            TokenType::Comment | TokenType::Whitespace | TokenType::StringLit |
            TokenType::Number | TokenType::Operator | TokenType::Punctuation => continue,

            // Shebang is fine as-is
            TokenType::Shebang => continue,

            // Keywords are fine
            TokenType::Keyword => continue,

            // Variables and command subs need quoting
            TokenType::Variable | TokenType::CommandSub | TokenType::ArrayExp => {
                // Skip special variables that don't need quoting
                if token.value == "$?" || token.value == "$$" || token.value == "$!" ||
                   token.value == "$#" || token.value == "${#arr[@]}" ||
                   token.value == "${#var[@]}" || token.value == "${#array[@]}" {
                    continue;
                }

                // Skip variables in assignments
                let prev_token = if let Some(t) = tokens.get(token.start - 1) {
                    t
                } else {
                    continue;
                };

                if prev_token.kind == TokenType::Other && prev_token.value == "=" {
                    continue;
                }

                // Skip variables in case statements
                let prev_prev_token = if let Some(t) = tokens.get(token.start - 2) {
                    t
                } else {
                    continue;
                };

                if prev_prev_token.kind == TokenType::Keyword && prev_prev_token.value == "case" {
                    continue;
                }

                // Skip variables in [[ ]] context
                let mut in_brackets = false;
                let mut bracket_depth = 0;
                for t in tokens.iter().take(token.start) {
                    if t.kind == TokenType::Punctuation {
                        if t.value == "[[" {
                            bracket_depth += 1;
                            in_brackets = true;
                        } else if t.value == "]]" {
                            bracket_depth -= 1;
                            in_brackets = false;
                        }
                    }
                }
                if in_brackets && bracket_depth > 0 {
                    continue;
                }

                // Skip variables in test/[[ ]] with -eq, -ne, etc.
                if token.value.starts_with("$") {
                    let var_name = &token.value[1..];
                    if var_name.chars().all(|c| c.is_ascii_digit()) {
                        continue;
                    }
                }

                suggestions.push(Suggestion {
                    start: token.start,
                    end: token.end,
                    original: token.value.clone(),
                    transformed: format!("\"{}\"", token.value),
                });
            }

            _ => continue,
        }
    }

    suggestions
}

fn apply_suggestions(input: &str, suggestions: &[Suggestion]) -> String {
    let mut result = String::new();
    let mut last_end = 0;

    for suggestion in suggestions {
        if suggestion.start > last_end {
            result.push_str(&input[last_end..suggestion.start]);
        }
        result.push_str(&suggestion.transformed);
        last_end = suggestion.end;
    }

    if last_end < input.len() {
        result.push_str(&input[last_end..]);
    }

    result
}

fn format_suggestion(suggestion: &Suggestion) -> String {
    format!("{}{}", suggestion.original, suggestion.transformed)
}

fn format_diff(input: &str, output: &str) -> String {
    let input_lines: Vec<&str> = input.lines().collect();
    let output_lines: Vec<&str> = output.lines().collect();

    let mut result = String::new();
    let mut line_num = 0;

    for (i, (in_line, out_line)) in input_lines.iter().zip(output_lines.iter()).enumerate() {
        line_num += 1;
        if in_line == out_line {
            result.push_str(&format!("{}\n", in_line));
        } else {
            result.push_str(&format!("\u001b[0;38;2;192;0;128m{}\u001b[m\n", in_line));
            result.push_str(&format!("\u001b[0;42m{}\u001b[m\n", out_line));
        }
    }

    result
}

fn format_transform(input: &str, output: &str) -> String {
    output.to_string()
}

fn format_syntax(input: &str, suggestions: &[Suggestion]) -> String {
    let mut result = String::new();
    let mut last_end = 0;

    for token in tokenize(input) {
        if token.start > last_end {
            result.push_str(&input[last_end..token.start]);
        }

        match token.kind {
            TokenType::Comment | TokenType::Shebang | TokenType::StringLit |
            TokenType::Number | TokenType::Operator | TokenType::Punctuation |
            TokenType::Whitespace => {
                result.push_str(&token.value);
            }
            TokenType::Keyword => {
                result.push_str(&format!("\u001b[0;1;3;38;2;120;144;96m{}\u001b[m", token.value));
            }
            TokenType::Variable | TokenType::CommandSub | TokenType::ArrayExp => {
                result.push_str(&format!("\u001b[0;38;2;63;127;207m{}\u001b[m", token.value));
            }
            _ => {
                result.push_str(&token.value);
            }
        }
        last_end = token.end;
    }

    if last_end < input.len() {
        result.push_str(&input[last_end..]);
    }

    result
}

fn format_syntax_suggest(input: &str, suggestions: &[Suggestion]) -> String {
    let mut result = String::new();
    let mut last_end = 0;

    for token in tokenize(input) {
        if token.start > last_end {
            result.push_str(&input[last_end..token.start]);
        }

        match token.kind {
            TokenType::Comment | TokenType::Shebang | TokenType::StringLit |
            TokenType::Number | TokenType::Operator | TokenType::Punctuation |
            TokenType::Whitespace => {
                result.push_str(&token.value);
            }
            TokenType::Keyword => {
                result.push_str(&format!("\u001b[0;1;3;38;2;120;144;96m{}\u001b[m", token.value));
            }
            TokenType::Variable | TokenType::CommandSub | TokenType::ArrayExp => {
                if suggestions.iter().any(|s| s.start == token.start && s.end == token.end) {
                    result.push_str(&format!("\u001b[0;42m\"\u001b[0;38;2;63;127;207m{}\u001b[0;42m\"\u001b[m", token.value));
                } else {
                    result.push_str(&format!("\u001b[0;38;2;63;127;207m{}\u001b[m", token.value));
                }
            }
            _ => {
                result.push_str(&token.value);
            }
        }
        last_end = token.end;
    }

    if last_end < input.len() {
        result.push_str(&input[last_end..]);
    }

    result
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 {
        let mut mode = Mode::Default;
        let mut files: Vec<String> = Vec::new();
        let mut stop_parsing = false;

        for arg in &args[1..] {
            if stop_parsing {
                files.push(arg.clone());
                continue;
            }

            if arg == "--help" || arg == "-h" {
                print_help();
                process::exit(0);
            } else if arg == "--version" {
                println!("{}", VERSION);
                process::exit(0);
            } else if arg == "--suggest" {
                mode = Mode::Suggest;
            } else if arg == "--syntax" {
                mode = Mode::Syntax;
            } else if arg == "--syntax-suggest" {
                mode = Mode::Default;
            } else if arg == "--transform" {
                mode = Mode::Transform;
            } else if arg == "--check" {
                mode = Mode::Check;
            } else if arg == "--replace" {
                mode = Mode::Replace;
            } else if arg == "--" {
                stop_parsing = true;
            } else if arg.starts_with('-') {
                eprintln!("{}: No such option.", arg);
                process::exit(3);
            } else {
                files.push(arg.clone());
            }
        }

        let stdin = io::stdin();
        let mut input: String = String::new();

        if files.is_empty() {
            stdin.read_to_string(&mut input).expect("Failed to read stdin");
        } else {
            for file in &files {
                let content = fs::read_to_string(file).expect(&format!("{}: No such file or directory (os error 2)", file));
                if !input.is_empty() {
                    input.push('\n');
                }
                input.push_str(&content);
            }
        }

        let tokens = tokenize(&input);
        let suggestions = find_suggestions(&tokens);

        let output = match mode {
            Mode::Default | Mode::SyntaxSuggest => {
                format_syntax_suggest(&input, &suggestions)
            }
            Mode::Syntax => {
                format_syntax(&input, &suggestions)
            }
            Mode::Suggest => {
                let transformed = apply_suggestions(&input, &suggestions);
                format_diff(&input, &transformed)
            }
            Mode::Transform => {
                let transformed = apply_suggestions(&input, &suggestions);
                format_transform(&input, &transformed)
            }
            Mode::Check => {
                if !suggestions.is_empty() {
                    process::exit(2);
                }
                return;
            }
            Mode::Replace => {
                let transformed = apply_suggestions(&input, &suggestions);
                if !files.is_empty() {
                    for (i, file) in files.iter().enumerate() {
                        let content = fs::read_to_string(&file).expect(&format!("{}: No such file or directory (os error 2)", file));
                        let transformed = apply_suggestions(&content, &suggestions);
                        fs::write(&file, &transformed).expect(&format!("Failed to write {}", file));
                    }
                }
                return;
            }
        };

        print!("{}", output);
    }
}

fn print_help() {
    println!("Shellharden: The corrective bash syntax highlighter.");
    println!();
    println!("Usage:");
    println!("\tshellharden [options] [files]");
    println!("\tcat files | shellharden [options] ''");
    println!();
    println!("Shellharden is a syntax highlighter and a tool to semi-automate the rewriting");
    println!("of scripts to ShellCheck conformance, mainly focused on quoting.");
    println!();
    println!("The default mode of operation is like `cat`, but with syntax highlighting in");
    println!("foreground colors and suggestive changes in background colors.");
    println!();
    println!("Options:");
    println!("\t--suggest         Output a colored diff suggesting changes.");
    println!("\t--syntax          Output syntax highlighting with ANSI colors.");
    println!("\t--syntax-suggest  Diff with syntax highlighting (default mode).");
    println!("\t--transform       Output suggested changes.");
