            }

            if arg == "--help" || arg == "-h" {
                print_help();
                process::exit(0);
            } else if arg == "--version" {
                println!("{}", VERSION);
                process::exit(0);
            } else if arg == "--suggest" {
                mode = Mode::Suggest;
            } else if arg == "--syntax" {
                mode = Mode::Syntax;
            } else if arg == "--syntax-suggest" {
                mode = Mode::Default;
            } else if arg == "--transform" {
                mode = Mode::Transform;
            } else if arg == "--check" {
                mode = Mode::Check;
            } else if arg == "--replace" {
                mode = Mode::Replace;
            } else if arg == "--" {
                stop_parsing = true;
            } else if arg.starts_with('-') {
                eprintln!("{}: No such option.", arg);
                process::exit(3);
            } else {
                files.push(arg.clone());
            }
        }

        let stdin = io::stdin();
        let mut input: String = String::new();

        if files.is_empty() {
            stdin.read_to_string(&mut input).expect("Failed to read stdin");
        } else {
            for file in &files {
                let content = fs::read_to_string(file).expect(&format!("{}: No such file or directory (os error 2)", file));
