                format_diff(&input, &_transformed)
            }
            Mode::Transform => {
                let _transformed = apply_suggestions(&input, &suggestions);
                format_transform(&input, &_transformed)
            }
            Mode::Check => {
                if !suggestions.is_empty() {
                    process::exit(2);
                }
                return;
            }
            Mode::Replace => {
                let _transformed = apply_suggestions(&input, &suggestions);
                if !files.is_empty() {
                    for (i, file) in files.iter().enumerate() {
                        let content = fs::read_to_string(&file).expect(&format!("{}: No such file or directory (os error 2)", file));
