        }

        eprintln!("DEBUG: Final input = {:?}", input);

        let tokens = tokenize(&input);
        let suggestions = find_suggestions(&tokens);

        eprintln!("DEBUG: Tokens: {:?}", tokens);
        eprintln!("DEBUG: Suggestions: {:?}", suggestions);

        let output = match mode {
