            let start = pos;
            while pos < chars.len() && chars[pos].is_whitespace() {
                pos += 1;
            }
            if start != pos {
                tokens.push(Token {
                    kind: TokenType::Whitespace,
                    start,
                    end: pos,
                    value: input[start..pos].to_string(),
                });
            }
            continue;
        }

        // Comments
        if c == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Comment,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Shebang
        if pos == 0 && c == '!' && pos + 1 < chars.len() && chars[pos + 1] == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Shebang,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // String literals
        if c == '"' || c == '\'' {
            let quote = c;
            let start = pos;
            pos += 1;
            while pos < chars.len() {
                if chars[pos] == '\\' && pos + 1 < chars.len() {
                    pos += 2;
                } else if chars[pos] == quote {
                    pos += 1;
                    break;
                } else {
                    pos += 1;
                }
            }
            tokens.push(Token {
                kind: TokenType::StringLit,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Numbers
        if c.is_ascii_digit() {
            let start = pos;
            while pos < chars.len() && chars[pos].is_ascii_digit() {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Number,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        // Operators and punctuation
        if c == '$' {
            let start = pos;
            if pos + 1 < chars.len() {
                let next = chars[pos + 1];
                if next == '?' || next == '#' || next == '!' || next == '*' || next == '@' {
                    pos += 1;
                    tokens.push(Token {
                        kind: TokenType::Variable,
                        start,
                        end: pos,
