enum Mode {
    Default,
    Syntax,
    Suggest,
    Transform,
    Check,
    Replace,
}

#[derive(Debug, Clone, PartialEq)]
enum TokenType {
    Comment,
    Shebang,
    Keyword,
    Variable,
    CommandSub,
    ArrayExp,
    StringLit,
    Number,
