fn tokenize(input: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut pos = 0;
    let chars: Vec<char> = input.chars().collect();

    while pos < chars.len() {
        let c = chars[pos];

        if c.is_whitespace() {
            let start = pos;
            while pos < chars.len() && chars[pos].is_whitespace() {
                pos += 1;
            }
            if start != pos {
                tokens.push(Token {
                    kind: TokenType::Whitespace,
                    start,
                    end: pos,
                    value: input[start..pos].to_string(),
                });
            }
            continue;
        }

        if c == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Comment,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if pos == 0 && c == '!' && pos + 1 < chars.len() && chars[pos + 1] == '#' {
            let start = pos;
            while pos < chars.len() && chars[pos] != '\n' {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Shebang,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c == '"' || c == '\'' {
            let quote = c;
            let start = pos;
            pos += 1;
            while pos < chars.len() {
                if chars[pos] == '\\' && pos + 1 < chars.len() {
                    pos += 2;
                } else if chars[pos] == quote {
                    pos += 1;
                    break;
                } else {
                    pos += 1;
                }
            }
            tokens.push(Token {
                kind: TokenType::StringLit,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c.is_ascii_digit() {
            let start = pos;
            while pos < chars.len() && chars[pos].is_ascii_digit() {
                pos += 1;
            }
            tokens.push(Token {
                kind: TokenType::Number,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c == '$' {
            let start = pos;
            if pos + 1 < chars.len() {
                let next = chars[pos + 1];
                if next == '?' || next == '#' || next == '!' || next == '*' || next == '@' {
                    pos += 1;
                    tokens.push(Token {
                        kind: TokenType::Variable,
                        start,
                        end: pos,
                        value: input[start..pos].to_string(),
                    });
                    continue;
                }
            }
            if pos + 1 < chars.len() && chars[pos + 1] == '(' {
                pos += 2;
                tokens.push(Token {
                    kind: TokenType::CommandSub,
                    start,
                    end: pos,
                    value: input[start..pos].to_string(),
                });
                continue;
            }
            if pos + 1 < chars.len() && chars[pos + 1] == '{' {
                let brace_start = pos + 1;
                pos += 1;
                while pos < chars.len() && chars[pos] != '}' {
                    pos += 1;
                }
                if pos < chars.len() {
                    pos += 1;
                }
                let value = input[brace_start..pos].to_string();
                if value.contains('@') || value.contains('*') {
                    tokens.push(Token {
                        kind: TokenType::ArrayExp,
                        start,
                        end: pos,
                        value,
                    });
                } else {
                    tokens.push(Token {
                        kind: TokenType::Variable,
                        start,
                        end: pos,
                        value,
                    });
                }
                continue;
            }
            pos += 1;
            tokens.push(Token {
                kind: TokenType::Variable,
                start,
                end: pos,
                value: input[start..pos].to_string(),
            });
            continue;
        }

        if c == '[' || c == ']' || c == '(' || c == ')' || c == '{' || c == '}' {
